def pack(chunks, budget):
    kept, used = [], 0
    for cid, score, tokens in sorted(chunks, key=lambda c: (-c[1], c[0])):
        if used + tokens <= budget:
            kept.append(cid)
            used += tokens
    return kept

def compact(history, max_tokens, keep_recent, summarise):
    est = lambda s: max(1, len(s) // 4)
    if sum(est(t) for t in history) <= max_tokens or keep_recent >= len(history):
        return list(history)
    old = history[:len(history) - keep_recent]
    recent = history[len(history) - keep_recent:]
    return ['SUMMARY: ' + summarise(old)] + recent

def position_report(results, max_gap):
    if not results:
        raise ValueError('no results')
    totals, hits = {}, {}
    for r in results:
        p = r['position']
        totals[p] = totals.get(p, 0) + 1
        hits[p] = hits.get(p, 0) + (1 if r['correct'] else 0)
    acc = {p: round(hits[p] / totals[p], 2) for p in totals}
    worst = sorted(acc.items(), key=lambda kv: (kv[1], kv[0]))[0][0]
    gap = round(max(acc.values()) - acc[worst], 2)
    return {'accuracy': acc, 'worst': worst, 'gap': gap, 'passed': gap <= max_gap}

